function setCookie(name, jsonData) {
  const jsonString = JSON.stringify(jsonData);
  const encodedValue = encodeURIComponent(jsonString);
  document.cookie = `${name}=${encodedValue}; expires=Fri, 31 Dec 9999 23:59:59 GMT; path=/`;
}

function getCookie(name) {
  const nameEQ = name + "=";
  const cookies = document.cookie.split(';');
  for(let i = 0; i < cookies.length; i++) {
    let cookie = cookies[i].trim();
    if (cookie.indexOf(nameEQ) === 0) {
      const encodedValue = cookie.substring(nameEQ.length);
      const jsonString = decodeURIComponent(encodedValue);
      return JSON.parse(jsonString);
    }
  }
  return null;
}

